parent = {1: 1, 2: 2, 3: 3}
def find(x):
    if parent[x] != x:
        parent[x] = find(parent[x])
    return parent[x]

edges = [(1, 1, 2), (2, 2, 3), (3, 1, 3)]
total = 0
for cost, a, b in edges:
    ra, rb = find(a), find(b)
    if ra != rb:
        parent[rb] = ra
        total += cost
print(total)

