from collections import deque
graph = {1: [2, 3], 2: [4], 3: [4], 4: []}
indegree = {1: 0, 2: 1, 3: 1, 4: 2}
queue = deque([1])
order = []
while queue:
    node = queue.popleft()
    order.append(node)
    for next_node in graph[node]:
        indegree[next_node] -= 1
        if indegree[next_node] == 0:
            queue.append(next_node)
print(order)

